<?php if(!defined('APP_ENTRY'))exit; $admin=$user['role']==='admin'; if($_SERVER['REQUEST_METHOD']==='POST'){if(!$admin)deny();try{$action=post('action');transaction(function()use($action){if($action==='create'){ $s=id_field('student_id');$c=id_field('class_id');execute('INSERT INTO enrollments(student_id,class_id) VALUES(?,?)',[$s,$c]);audit('enroll',"student #$s / class #$c");}elseif($action==='delete'){confirmed();$id=id_field('id');if(!execute('DELETE FROM enrollments WHERE id=?',[$id]))throw new DomainException('Enrollment not found.');audit('unenroll',"enrollment #$id");}else deny();});flash('Enrollment updated.');redirect('enrollments');}catch(DomainException $ex){$error=$ex->getMessage();}catch(PDOException $ex){error_log_file($ex);$error='Duplicate enrollment, invalid record, or existing grades prevent this change.';}}
$q='%'.search_term().'%';$sql='SELECT en.id,s.name,c.class_name,COALESCE(t.name,c.legacy_teacher,\'Unassigned\') teacher FROM enrollments en JOIN students s ON s.id=en.student_id JOIN classes c ON c.id=en.class_id LEFT JOIN staff_accounts t ON t.id=c.teacher_id WHERE (s.name LIKE ? OR c.class_name LIKE ?)';$data=$admin?rows($sql.' ORDER BY s.name',[$q,$q]):rows($sql.' AND c.teacher_id=? ORDER BY s.name',[$q,$q,$user['id']]);$columns=['name'=>'Student','class_name'=>'Class','teacher'=>'Teacher'];if(!$admin){require __DIR__.'/../includes/read_table.php';return;}$students=rows('SELECT id,name FROM students ORDER BY name');$classes=rows('SELECT id,class_name FROM classes ORDER BY class_name'); ?>
<?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><section class="panel"><h2>Enroll a student</h2><form method="post" class="grid-form"><?=csrf_field()?><input type="hidden" name="action" value="create"><label>Student<select name="student_id" required><option value="">Choose student</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"<?=selected(post('student_id'),$s['id'])?>><?=e($s['name'])?></option><?php endforeach;?></select></label><label>Class<select name="class_id" required><option value="">Choose class</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>"<?=selected(post('class_id'),$c['id'])?>><?=e($c['class_name'])?></option><?php endforeach;?></select></label><div class="form-actions"><button>Enroll student</button></div></form></section><section class="panel"><div class="toolbar"><h2>Enrollments</h2><?php search_form($page);?></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Class</th><th>Teacher</th><th>Actions</th></tr></thead><tbody><?php foreach($data as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['class_name'])?></td><td><?=e($r['teacher'])?></td><td><?php delete_form($page,(int)$r['id']);?></td></tr><?php endforeach;?><?php if(!$data):?><tr><td colspan="4">No matching records.</td></tr><?php endif;?></tbody></table></div></section>
